mapper.select:
SELECT E.*, O.LOCATION COMP_NAME,D.LOCATION CHARGE_NAME,J.LOCATION COMORG_NAME
FROM COMM_EMPLOYEE E
LEFT JOIN COMM_ORGANIZATION O ON(E.COMPID=O.COMPID)
LEFT JOIN COMM_DEPARTMENT D ON(E.DEPID=D.DEPID)
LEFT JOIN COMM_JOB J ON(E.JOBID=J.JOBID) WHERE EMPSTATUS != 'Loff'
AND GENDER = #{gender}
AND ISDISABLED = #{isdisabled}
AND INSTR(EMPNAME,#{empname} ) > 0
AND CERTIFICATE_TYPE = #{certificateType}
AND CERTIFICATE_NUMBER =
    #{certificateNumber}

AND E.BADGE = #{badge}
AND E.COMPID = #{compid}
AND OFFICEPHONE = #{officephone}
AND E.DEPID = #{depid}
AND MOBILETELPHONE = #{mobiletelphone}

mapper.delete:
DELETE
FROM
COMM_EMPLOYEE where badge != 'sysadmin'
AND EID = #{eid}
AND E.BADGE = #{badge}
AND E.COMPID = #{compid}

mapper.select:
SELECT E.BADGE FROM PPM_EMP_VIEW E WHERE E.HEADSHIP IS NOT NULL AND E.DEPID = (
SELECT T.DEPID FROM PPM_EMP_VIEW T WHERE T.BADGE = #{userId}
)

SELECT X.BADGE FROM PPM_EMP_VIEW X WHERE X.EIDHR = (
SELECT A.DIRECTOR FROM COMM_DEPARTMENT A WHERE A.DEPID = (
SELECT T.DEPID FROM PPM_EMP_VIEW T WHERE T.BADGE = #{userId}
)
)

SELECT T.BADGE,T.EMPNAME,T.EID FROM COMM_EMPLOYEE T
T.BADGE = #{badge} AND INSTR(T.EMPNAME,#{empname} ) > 0 AND INSTR(T.SPELLNAME,#{spellname}) > 0 AND INSTR(T.fullname , #{dep}) > 0 AND
ROWNUM <= ${proLoadNumber}

select sum(c) from (
select count(depid) c from ppm_emp_view where depid = #{id}
union
select count(depid) c from comm_parttimejob where depid = #{id} and isdisable = '0'
)

SELECT oai.AUTH_ENCODING FROM OPERA_USER_ROLE_REL ourr
LEFT JOIN OPERA_AUTH_INFO oai ON ourr.URR_ROLEID = oai.ROL_ID
WHERE ourr.URR_USERID = #{userId}

mapper.insert:
INSERT INTO RESEARCH_MANAGER_EMPLOYEE (
EID , BADGE , EMPNAME , COMPID , DEPID , JOBID , HEADSHIP , EMPSTATUS , EMPAUTH , AUTHPROPERTY , GENDER , BIRTHDAY , CERTIFICATE_TYPE, CERTIFICATE_NUMBER, OFFICEPHONE , MOBILETELPHONE , REMARK , ISDISABLED , UPDATEFLG , LASTUPDATEDATE , EIDHR , BOARDLINE , REPORTTO , FULLNAME , SPELLNAME , SHORTPHONE ,
) VALUES(
#{eid} , #{badge} , #{empname} , #{compid} , #{depid} , #{jobid} , #{headship} , #{empstatus} , #{empauth} , #{authproperty} , #{gender} , #{birthday} , #{certificateType}, #{certificateNumber}, #{officephone} , #{mobiletelphone} , #{remark} , #{isdisabled} , #{updateflg} , #{lastupdatedate} , #{eidhr} , #{boardline} , #{reportto} , #{fullname} , #{spellname} , #{shortphone} ,
)
